        'legal.privacy.section_6.item_5' => 'Obtenir la portabilité des données (dans certains cas)',
        'legal.privacy.section_6.item_6' => 'Déposer une plainte auprès d\'une autorité de protection des données',
        'legal.privacy.section_6.p2' => 'Pour exercer ces droits, contactez-nous à : {email}',
        'legal.privacy.section_7.heading' => '7. Sécurité de vos données.',
        'legal.privacy.section_7.p1' => 'Nous prenons des mesures administratives, techniques et physiques raisonnables pour protéger vos informations contre la perte, le vol et l\'utilisation ou l\'accès non autorisé.',
        'legal.privacy.section_8.heading' => '8. Cookies',
        'legal.privacy.section_8.p1' => 'Notre site web utilise des cookies pour améliorer l\'expérience utilisateur et analyser l\'utilisation du site. Vous pouvez gérer vos préférences de cookies via les paramètres de votre navigateur.',
        'legal.privacy.section_9.heading' => '9. Transferts internationaux de données.',
        'legal.privacy.section_9.p1' => 'Si vous êtes situé en dehors du Canada, vos informations peuvent être transférées vers le Canada ou d\'autres pays et y être traitées, même si leurs lois sur la protection des données sont différentes.',
        'legal.privacy.section_10.heading' => '10. Liens vers des sites tiers.',
